ErrCode SbiDdeControl::GetLastErr( const DdeConnection* pConv )
{
    if( !pConv )
    {
        return ERRCODE_NONE;
    }
    tools::Long nErr = pConv->GetError();
    if( !nErr )
    {
        return ERRCODE_NONE;
    }
    if( nErr < DDE_FIRSTERR || nErr > DDE_LASTERR )
    {
        return ERRCODE_BASIC_DDE_ERROR;
    }
    return nDdeErrMap[ 2 * (nErr - DDE_FIRSTERR) + 1 ];
}
